package org.sleepwell.app;

import android.app.job.*;
import android.content.*;
import android.os.PersistableBundle;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Separate future-night consent. No history backfill, notes, event deletion or blind retries. */
final class AutoCalendar {
 static final int JOB=21683;
 private static final String FILE="automatic_calendar_v1";
 private static final Object LOCK=new Object();
 private static final ConcurrentMap<AtomicBoolean,String> OWNERS=new ConcurrentHashMap<>();
 static final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"Automatic calendar queue"));
 static final class Config {
  final boolean enabled;final long calendar,revision,since;final String name,fingerprint;
  Config(boolean enabled,long calendar,String name,String fingerprint,long revision,long since){this.enabled=enabled;this.calendar=calendar;this.name=name;this.fingerprint=fingerprint;this.revision=revision;this.since=since;}
 }
 static final class Item {
  final String token,state,issue;final long record,start,end,revision;
  Item(String token,long record,long start,long end,long revision,String state,String issue){this.token=token;this.record=record;this.start=start;this.end=end;this.revision=revision;this.state=state;this.issue=issue;}
  Item state(String phase,String notice){return new Item(token,record,start,end,revision,phase,notice);}
 }
 private static SharedPreferences preferences(Context c){return c.getApplicationContext().getSharedPreferences(FILE,Context.MODE_PRIVATE);}
 static Config load(Context c){SharedPreferences p=preferences(c);return new Config(p.getBoolean("enabled",false),p.getLong("calendar",0),p.getString("name",""),p.getString("fingerprint",""),p.getLong("revision",0),p.getLong("since",0));}
 static String status(Context c){try{return preferences(c).getString("status","");}catch(RuntimeException invalid){return "Automatic calendar settings need review.";}}
 private static void notice(Context c,String message){preferences(c).edit().putString("status",message).commit();}
 static List<Item> items(Context c){try{JSONArray raw=new JSONArray(preferences(c).getString("queue","[]"));if(raw.length()>32)throw new JSONException("Too many pending exports");List<Item> out=new ArrayList<>();Set<String> tokens=new HashSet<>();for(int n=0;n<raw.length();n++){JSONObject r=raw.getJSONObject(n);String token=r.getString("token"),phase=r.getString("state"),issue=r.getString("issue");long id=SensorProvenance.whole(r,"record"),start=SensorProvenance.whole(r,"start"),end=SensorProvenance.whole(r,"end"),revision=SensorProvenance.whole(r,"revision");if(!BackupRuntime.nonce(token)||!tokens.add(token)||id<=0||start<=0||end<=start||end-start>SensorProvenance.MAX_SESSION||revision<1||!Set.of("QUEUED","RUNNING","VERIFIED","NEEDS_REVIEW","CANCELLED").contains(phase)||issue.length()>500)throw new JSONException("Invalid automatic export receipt");out.add(new Item(token,id,start,end,revision,phase,issue));}return out;}catch(JSONException invalid){throw new IllegalStateException("Automatic calendar receipts need attention; no pending event will be replayed.",invalid);}}
 private static String encode(List<Item> items){try{JSONArray out=new JSONArray();for(Item i:items)out.put(new JSONObject().put("token",i.token).put("record",i.record).put("start",i.start).put("end",i.end).put("revision",i.revision).put("state",i.state).put("issue",i.issue));return out.toString();}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
 private static void write(Context c,List<Item> items,String message){if(!preferences(c).edit().putString("queue",encode(items)).putString("status",message).commit())throw new IllegalStateException("Automatic export state could not be stored. Review calendar receipts before retrying.");}
 static void save(Context c,boolean enabled,CalendarEventWrites.Calendar destination,long expected){synchronized(LOCK){Config old=load(c);if(old.revision!=expected)throw new IllegalStateException("Calendar settings changed. Reopen before saving.");if(old.revision==Long.MAX_VALUE)throw new IllegalStateException("Calendar settings revision is unavailable.");if(enabled){if(destination==null||!CalendarEventWrites.allowed(c))throw new IllegalStateException("Allow calendar access and choose a writable calendar first.");boolean found=false;for(CalendarEventWrites.Calendar candidate:CalendarEventWrites.factory.open(c).calendars())if(candidate.id==destination.id&&candidate.fingerprint.equals(destination.fingerprint))found=true;if(!found)throw new IllegalStateException("The selected calendar changed. Reload and choose again.");}
  if(enabled&&old.enabled&&destination.id==old.calendar&&destination.fingerprint.equals(old.fingerprint)){notice(c,"Existing future-night consent kept. No history was exported.");schedule(c);return;}
  List<Item> queue=null;try{queue=new ArrayList<>();for(Item i:items(c))queue.add(i.state.equals("QUEUED")||i.state.equals("RUNNING")?i.state("CANCELLED","Consent changed. Check any earlier provider write in this record's direct-export receipts."):i);}catch(RuntimeException unreadable){if(enabled)throw unreadable;queue=null;}
  SharedPreferences.Editor e=preferences(c).edit().putBoolean("enabled",enabled).putLong("revision",old.revision+1).putLong("since",System.currentTimeMillis()).putString("status",enabled?"Enabled for recordings started after this Save. Existing history was not exported.":"Off. Future requests stopped; existing calendar events remain.");if(queue!=null)e.putString("queue",encode(queue));if(enabled)e.putLong("calendar",destination.id).putString("name",destination.name).putString("fingerprint",destination.fingerprint);if(!e.commit())throw new IllegalStateException("Automatic calendar consent could not be saved.");cancelJob(c);
 }}
 /** Called after successful production recording commit, never by imports or history restore. */
 static void ended(Context context,long id,long start,long end,boolean production){if(!production||id<=0||Records.factory!=Records.PRODUCTION||CalendarEventWrites.factory!=CalendarEventWrites.PLATFORM)return;Context c=context.getApplicationContext();worker.execute(()->{try{synchronized(LOCK){Config config=load(c);if(!config.enabled||start<config.since||end<=start||end-start>SensorProvenance.MAX_SESSION)return;List<Item> queue=new ArrayList<>(items(c));for(Item i:queue)if(i.record==id&&i.start==start&&i.end==end)return;
   while(queue.size()>=32){int removable=-1;for(int n=0;n<queue.size();n++)if(Set.of("VERIFIED","CANCELLED").contains(queue.get(n).state)){removable=n;break;}if(removable<0)throw new IllegalStateException("32 exports need review. This new night was kept locally but not queued.");queue.remove(removable);}
   queue.add(new Item(UUID.randomUUID().toString(),id,start,end,config.revision,"QUEUED",""));write(c,queue,"A new completed night is queued. Calendar app/server sync is separate.");schedule(c);
  }}catch(RuntimeException failed){notice(c,"The night was saved locally. Automatic calendar export needs review.");}});}
 static void resume(Context context){Context c=context.getApplicationContext();worker.execute(()->{try{synchronized(LOCK){List<Item> queue=new ArrayList<>();boolean changed=false;for(Item i:items(c)){if(i.state.equals("RUNNING")&&!OWNERS.containsValue(i.token)){queue.add(i.state("NEEDS_REVIEW","The earlier provider outcome is unknown. Open direct-export receipts; this request will not replay."));changed=true;}else queue.add(i);}if(changed)write(c,queue,"An interrupted calendar write needs review.");schedule(c);}}catch(RuntimeException failed){notice(c,"Calendar queue could not be resumed. Review settings.");}});}
 private static void schedule(Context c){Config config=load(c);if(!config.enabled||items(c).stream().noneMatch(i->i.state.equals("QUEUED")&&i.revision==config.revision))return;PersistableBundle extra=new PersistableBundle();extra.putLong("revision",config.revision);JobScheduler jobs=c.getSystemService(JobScheduler.class);if(jobs==null||jobs.schedule(new JobInfo.Builder(JOB,new ComponentName(c,AutoCalendarService.class)).setExtras(extra).setMinimumLatency(5000).setPersisted(true).build())!=JobScheduler.RESULT_SUCCESS)notice(c,"The night is queued, but Android did not accept its background job. Reopen to resume.");}
 static void cancelJob(Context c){JobScheduler jobs=c.getSystemService(JobScheduler.class);if(jobs!=null)jobs.cancel(JOB);}
 /** Fences queued/in-flight ownership before record replacement/removal. External events remain. */
 static void historyChanging(Context c){synchronized(LOCK){SharedPreferences p=preferences(c);long revision;try{revision=p.getLong("revision",0);}catch(RuntimeException invalid){revision=0;}SharedPreferences.Editor e=p.edit().putString("queue","[]").putString("status","Pending export receipts were cleared with local history changes. Existing calendar events remain.");if(revision>=Long.MAX_VALUE-1)e.putBoolean("enabled",false).putLong("revision",Long.MAX_VALUE);else e.putLong("revision",revision+1);if(!e.commit())throw new IllegalStateException("Pending automatic calendar exports could not be invalidated. Retry the history operation.");cancelJob(c);}}
 private static boolean owned(Context c,Config config,Item item,AtomicBoolean cancelled){synchronized(LOCK){if(cancelled.get()||Records.factory!=Records.PRODUCTION||CalendarEventWrites.factory!=CalendarEventWrites.PLATFORM)return false;Config live=load(c);if(!live.enabled||live.revision!=config.revision||live.calendar!=config.calendar||!live.fingerprint.equals(config.fingerprint))return false;return items(c).stream().anyMatch(i->i.token.equals(item.token)&&i.state.equals("RUNNING")&&i.revision==config.revision);}}
 static void run(Context context,long revision,AtomicBoolean cancelled,Runnable done){Context c=context.getApplicationContext();worker.execute(()->{Config config;Item pending;try{synchronized(LOCK){config=load(c);if(!config.enabled||config.revision!=revision||cancelled.get()){done.run();return;}List<Item> queue=new ArrayList<>(items(c));pending=queue.stream().filter(i->i.state.equals("QUEUED")&&i.revision==revision).findFirst().orElse(null);if(pending==null){done.run();return;}for(int n=0;n<queue.size();n++)if(queue.get(n).token.equals(pending.token))queue.set(n,pending.state("RUNNING","Provider work admitted; its outcome is not yet verified."));write(c,queue,"Saving a completed night to the selected local calendar…");OWNERS.put(cancelled,pending.token);}
  CalendarEventWrites.Calendar calendar=new CalendarEventWrites.Calendar(config.calendar,config.name,config.fingerprint);CalendarEventWrites.automatic(c,pending.record,pending.start,pending.end,calendar,()->owned(c,config,pending,cancelled),state->worker.execute(()->{try{synchronized(LOCK){List<Item> queue=new ArrayList<>(items(c));boolean verified=state.error.isEmpty()&&state.status.startsWith("Saved to the local calendar provider.");String message=verified?"Saved and verified in the local calendar. Remote sync is controlled by your calendar app.":"This export needs review in the saved record's direct-calendar receipts. No automatic retry will insert another event.";for(int n=0;n<queue.size();n++)if(queue.get(n).token.equals(pending.token)&&queue.get(n).state.equals("RUNNING"))queue.set(n,pending.state(verified?"VERIFIED":"NEEDS_REVIEW",message));write(c,queue,message);schedule(c);}}catch(RuntimeException ignored){}finally{OWNERS.remove(cancelled);done.run();}}));
 }catch(RuntimeException failed){notice(c,"Automatic calendar export needs review; no request was replayed.");done.run();}});}
 static void interrupted(Context context,AtomicBoolean cancelled){cancelled.set(true);String token=OWNERS.remove(cancelled);Context c=context.getApplicationContext();worker.execute(()->{try{synchronized(LOCK){List<Item> queue=new ArrayList<>();for(Item i:items(c))queue.add(i.state.equals("RUNNING")&&i.token.equals(token)?i.state("NEEDS_REVIEW","Android stopped this job. Check direct-export receipts before retrying."):i);write(c,queue,"Background export interrupted. Possible provider writes are not replayed.");}}catch(RuntimeException ignored){}});}
 private AutoCalendar(){}
}
